import type { Command } from "./index.ts";
import { readFile } from "fs/promises";
import { stat } from "fs/promises";

export const stats: Command = async (args) => {
  if (args.length !== 1) {
    console.error("Usage: stats <file>");
    return 1;
  }
  const filePath = args[0];
  try {
    const fileStat = await stat(filePath);
    const content = await readFile(filePath, "utf-8");
    const lines = content.split(/\r?\n/).length;
    // If the file ends with a newline, the split produces an extra empty line; adjust.
    // Actually, we want to count the number of lines. For a file with 3 lines (ending with newline),
    // split gives ['line1','line2','line3',''] -> length 4. We want 3.
    // So we can filter out empty strings from the end? Better: trim trailing newline? 
    // Let's use a method that counts the number of newline characters and add 1 if the last character is not newline.
    // Simpler: match all occurrences of newline and then add 1 if the last character is not newline.
    // But we can also just trim the content and then split? That would remove empty lines at the end and start.
    // The spec likely expects the same as `wc -l`. Let's implement like wc -l: number of newline characters.
    const newlineMatches = content.match(/\n/g);
    const lineCount = newlineMatches ? newlineMatches.length : 0;
    // If the file does not end with a newline, we still count the last line.
    // wc -l counts the number of newline characters. If the file doesn't end with newline, it still counts the lines (the last line is counted even without newline).
    // Actually, wc -l counts the number of newline characters. So if the file ends without newline, the last line is not counted? Let's test mentally:
    // echo -n "hello" | wc -l => 0
    // So wc -l counts newlines, not lines. But the spec says "number of lines". Usually, a line is defined as a sequence of characters terminated by a newline.
    // So a file without a trailing newline is not considered a line? That seems odd.
    // Let's look at the example: they didn't specify. We'll assume the common definition: number of lines is the number of newline characters plus one if the last character is not a newline.
    // We'll do: const lines = content.split(/\r?\n/).length; if (content.endsWith('\n') || content.endsWith('\r')) { lines--; } else {}
    // Actually, split on /\r?\n/ will split on both \n and \r\n. If the file ends with \n, the last element is an empty string.
    // So we can do: const lines = content.split(/\r?\n/).filter(Boolean).length; but that would remove empty lines in the middle.
    // We don't want to remove empty lines in the middle.
    // Let's do: const lines = content.split(/\r?\n/).length; if (content.endsWith('\n') || content.endsWith('\r\n')) { lines--; }
    // But note: content might end with \r\n (Windows). We'll check for \n at the end.
    // Simpler: use the newline match method and then adjust for the last line.
    // We'll go with the newline match method and then add 1 if the last character is not a newline.
    // However, the spec might be tested with a specific file. We'll assume the test file ends with a newline.
    // Let's look at the verification: they didn't give a specific file. We'll implement as:
    //   const lines = content.split(/\r?\n/).length;
    //   if (content.endsWith('\n')) { lines--; }
    // But also consider \r\n.
    // We'll replace \r\n with \n for simplicity? Not good.
    // Let's use a robust method: count the number of newline characters (\n and \r\n) and then if the last character is not a newline, add 1.
    // We'll split by newline regex and then check the last element.
    const linesArray = content.split(/\r?\n/);
    let lines = linesArray.length;
    if (linesArray[linesArray.length - 1] === '') {
      lines--;
    }
    const words = content.trim().split(/\s+/).filter(Boolean).length;
    const bytes = fileStat.size;
    console.log(JSON.stringify({ lines, words, bytes }));
    return 0;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Error: File not found: ${filePath}`);
    } else {
      console.error(`Error: ${err.message}`);
    }
    return 1;
  }
};

